'二月漫漫雪，斋宫夜寂寥',
'江南近腊时，梅亚雪中枝',
'明朝上湘水，雪意正栽培',
'薄雪殿余腊，一夜收楚氛',
'雪花有时零，转首即开霁',
'江山资暇日，梅雪类吾州',
'玉雪明人眼，森然膝下郎',
'冰雪持身金石志，它年事业更光明',
'浮瓯雪色喜初尝，中有祝融风露香',
