'但得数枝花似雪，何须裁截伴枯筇',
'嘉此烟雾姿，本无霜雪辱',
'雪舞愁云外，花飞泪眼中',
'春泥雪消淮上路，东风浪头惊客𫇛',
'美人亭亭面如雪，纤手当弦金杆拨',
'随驾上楼同看雪，万重宫殿一时新',
'平明诸山雪，烂漫铺琳球',
'玄龛剖山腹，六月霜雪至',
'爱此千树雪，高低不胜繁',
'风月精神珠玉骨，冰雪簪珥琼瑶珰',
'寻山把酒岂易得，客路霰雪衣裘单',
'山阴半夜寒欲冰，晚望高峰看新雪',
'寒云崩腾不成雪，北风吹窗灯半灭',
'朝裘风劲黑貂暖，夜帷雪满青毡重',
'布衾蒙头但欲睡，瞥见檐雪如飞尘',
'近者皇天忽悔祸，雨施云行咸澡雪',
'城头月落霜如雪，楼头五更声欲绝',
'雪野挑蔬瘦，霜天暖酒迟',
'三更风雪暗，一点佛龛灯',
'雪压移来竹，霜萎自种蔬',
'残雪暗随冰笋滴，新春偷向柳梢归',
'苍茫腊雪欲成泥，又见东风上柳枝',
