'久拼两鬓如霜雪，直欲樵渔过此生',
'阅世祝公松柏寿，从来霜雪不能寒',
'南山春雪冻云凝，暗火青灯急霰声',
'山川积雪坚冰地，舟楫长淮古汳间',
'临汝城中春雪消，望嵩楼上对岧峣',
