'更谢晴明好山色，数峰残雪在檐前',
'孤阁鸣钟天黯惨，寒山戴雪晚峥嵘',
'梅梢柳眼弄春娇，云暖南山腊雪消',
'想见竟陵残雪里，新梅点雪橘垂金',
'谁令万屋淋漓雪，犹作长安半夜寒',
'任遣墙头疑是雪，欲教园木早知春',
'脉脉无言亦有期，雪中狂杀羽林儿',
'疏梅半落雪中香，想子孤吟对酒缸',
'因风自袅还成态，与雪争妍却要寒',
'腊残春近独消魂，残雪长安千万门',
'认得君家门上雪，易知何事却难忘',
'去年慈德门东雪，永夜宫廊喝探喧',
'风格孤高又国香，故教小雪发新妆',
'晨起千林腊雪新，数枝云梦泽南春',
'吐词分葩有国香，近君如雪六月凉',
'幕云当昼合，袍雪与风来',
'北风号空庭，山雪鸣急霰',
'江南春尚早，余雪冒山椒',
'那知事大谬，暮雪卷风至',
'去年一尺雪，新泽至已屡',
'故园陈墟太昊祠，腊雪消后融春泥',
'雪霁山堆黛，江晴日炫金',
'风烟调柳态，冰雪彻梅心',
'如丝苣甲饤春盘，韭叶金黄雪未干',
'水国穷冬犹未雪，木牙草色似春余',
'腊日开门雪满山，愁阴短景岁将阑',
