'思家对雪诚何味，只与群山鬭白头',
'雨露草必生，雪霜松不死',
'雨过霜风急，帆飞雪浪分',
'看山浑不倦，待得雪峰青',
'独留白雪花，洒此千尺翠',
'记着今朝胜，山明松雪寒',
'白雪链多齐日月，黄芽服久出乾坤',
'沆瀣露中分白雪，华池水内养黄芽',
'黄鹂过处金穿柳，白鹭飞时雪点山',
'秋徂风雨多，欲作雪霜迓',
'昔我初为入秦客，残雪埋关闭长陌',
