'九原杀气横天高，朔风吹雪沾霜刀',
'雪发丹心被，君恩宝剑知',
'三峡桥边春见雪，落星寺里暮闻钟',
'烟遮晃白初疑雪，日映斓斑却是花',
'扁舟雪夜兴，千载风流存',
'吾乡多霜雪，岂不坂路长',
'日出辉辉收霰雪，仿佛拜命若可亲',
'为我寄谢钱都统，鬓间不许霜雪积',
'奈我贫病何，萧寺多积雪',
'钟阜被朔雪，暂与我何娱',
'京华前岁此时雪，独卧先庐亦寂寥',
'志苦言危凛雪霜，何人敢唤作刘郎',
'负雪披霜不得依，梅寒恨不出幽诗',
'风雪担书梦，旌旗从使行',
'舒虹荡月明珠过，积雪迷云小稻香',
'雪迷石岭上，月在草堂中',
'此雪问谁偏最喜，羯胡得意逞天骄',
'南陆朱明驭，西阑白雪山',
'少林续焰事堪可，腊夜梅开雪后枝',
'妙明一句威音外，折角泥牛雪里眠',
'中夜雪打窗，灯暗火照屋',
'孤僧雪中归，白马度堑谷',
'我独冰雪间，肘见冠缨绝',
'猎回汉苑秋高夜，饮罢秦台雪作天',
'东吴杨柳云中渚，南越梅花雪外洲',
'醉眸觑纸聊一扫，落花飞雪声漫漫',
'雪消风软山苍然，杏梢红破胭脂寒',
'霜风惨黄叶，雪雨埋朝暾',
'母年可惧髪委雪，诸父骈头埋九原',
'乾坤子初无薄厚，恩为雨露威雪霜',
'前年深冬一丈雪，岩拥朝阳渡黄叶',
'将谓雪消无觅处，元来只在毫端住',
