'长松竟拔徂徕雪，骏马争驰冀北风',
'几处梅花傲残雪，不随桃李事轻红',
'江天吹雪不胜繁，南北东西晚更昏',
'篮舆还自斗边城，雪夜乾坤分外清',
'寒雪欻随残腊尽，暖风端逐早春回',
'独行山雪下，孤泊夜潮生',
'风窗灯易灭，雪屋夜增寒',
'今期甚好雪，纷纷如秋月',
'岩冷秋空月，林清雪夜猱',
'出俗旧题留雪苑，卧云幽兴梦天台',
'阴崖竹树犹欹雪，暖砌莺花已觉春',
'庭梅向日花全拆，岳树连云雪未消',
'眠云未负他年约，看雪难忘尽日吟',
