'看云欹尽日，书雪握多时',
'短髪全成雪，残花半逐风',
'雪搅长空马僵立，偷营今夜度胶河',
'可怜万事不干身，凭栏且看千峰雪',
'叶浮晚水愁眉细，絮落春衣雪片轻',
'腊深空冒雪，春老始开花',
'径静苔长绿，山寒雪未消',
'冲雪登高山，乘月泛平湖',
'空庭何所有，冷落唯松雪',
'岩桂翠浓深雪夜，井桐黄落暮秋时',
'不忍多时听，吟髭雪暗侵',
'楼台一簇出云杪，激雪浪生寒涧风',
'雪中未问和羹事，且向百花头上开',
'云门雪窦阻清赏，恍然目想心如遗',
'细风先动柳，残雪不藏梅',
'凋残片叶坠虚庭，泠寂何人立深雪',
'雪老当年曾入岭，真禅今日又思乡',
'江城雨雪书名纸，不谒鸿儒更谒谁',
'岩近生风雷，天遥新冰雪',
'如何苦雪霜，后凋蠧松竹',
'洁已已能成玉雪，为人犹自作蓍龟',
'那知凛凛梢云者，自有松筠傲雪霜',
'风前火烈逢真玉，雪后大寒见老松',
'红薇花阴煮玉醴，满瓯飞雪置我旁',
'避寒何处过雪霜，依旧飞来语音好',
'弄雪仙人淡纻衣，烟裙不着鸳鸯绣',
'风吹破屋雪入怀，独与蜗牛夜争席',
'岂惟大旱有云霓，解作丰年雪花白',
'山腰余雪瘦，天面冷云低',
'曛黄飞雪已填门，独夜人依老柳根',
'州人欲识余霙雪，寄与飞廉百里风',
'东风未破桃花萼，雪压余英蝶乱飞',
'阴岩有积雪，竟日无行辀',
'北风多雪霜，严冬无劲草',
'梦回天与玉麒麟，争似峩眉千仞雪',
'雪中落落多乔松，苍枝偃干如虬龙',
'朂清祗饮洛口水，祁寒欲避西山雪',
'雪花笼石商皓首，枫叶满山秦赭衣',
