'作雪晓天梅萼重，压尘小雨马蹄轻',
'春入小桃浑绮绣，风回残雪半尘沙',
'作梅后日看调鼎，拟雪前人欲散空',
'一笑行抛汉水湄，野梅残雪照旌旗',
