'顽云垂翼山碉暗，乔麦饶花雪岭开',
'行经阊阖云生足，归到方壶雪弄花',
'风卷寒云雪压船，楼台隐约隔明烟',
'风威带雪连秦树，山势将寒入蜀门',
'奈何忽霜雪，星星欲无余',
'时时要同盘，穿雪菜甲动',
'南徐祖令侬自知，雪打西安尝豆糜',
'夜阑白雪回歌扇，舞彻红灯照酒卮',
'春催江上红梅发，雪唤淮南青子来',
'兴来下马索酒觞，雪打战袍殊未央',
'近君白雪热何有，高谈一激锥囊脱',
'玉仙曾此驻云车，日薄窗纱映雪肤',
'清淡不媚春，挺挺凌霜雪',
'去月霜雪交，咫尺涩如棘',
'得兴雪月交，理棹会一访',
'积雪未亏日还没，云气黯惨愁不释',
'只今雪思未渠央，准拟作花大如席',
