'一段画图冬卧雪，平生乐事日翻书',
'三元盛礼冠年华，翼日朝堤雪覆沙',
'积雪满山寒不释，碧琅玕绕玉楼台',
'道傍苍木老霜雪，涧畔野草随春秋',
'堕此吠雪国，烈火烂不收',
'积雪日出杲，雪飞梅已残',
'风引旆旌趋魏阙，雪晴宇宙灭天尘',
'芦峰深处无人到，门前雪压枯松倒',
'山近雪云密，风动梅香寒',
'驱除腊雪烦梅蘂，收拾春风倩柳条',
