'雪浪翻天迷赤壁，令人西望忆潘郎',
'夜长乘雪出诗轴，十里银光摇素练',
'应怜我穷被雪压，冷屋号寒命如线',
'兰台赋风不赋雪，好色岂殊蜂蝶恋',
