'山前腊雪想纷纷，风到南讹尽处村',
'雪曾前岁有，地过此邦无',
'南来不觉两秋砧，览照惊呼雪满簪',
'天垂望羌山，雪汁融朝暾',
'秦云惨雪趋朝路，吴雨肥梅按部天',
