'冻云未放僧窗晓，折竹方知夜雪深',
'水阁飏烟晴试茗，雪窗剪烛夜论诗',
'清弹一曲悲风远，绝唱千章白雪新',
'雪摧枯虑默如喑，秋压寒松老不禁',
