'君看雪霜根，岂受桃李妒',
'苔痕记拄杖，雪影傍跏趺',
'蔬畦甚寂寞，亦受霜雪侵',
'野桧多鳞甲，寒松半雪霜',
'但闻玉雪郎，去作猿鹤主',
