'九夏炎炎雪正飞，三冬飒飒华初放',
'林木萧条复本根，严霜冻雪鏁松门',
'厖头覆霜雪，碧眼照针缕',
'清妍梅著雪，圆美珠走盘',
'绕树三匝已，投空雪飞翻',
'安得僧舍雪，霏微湿茶烟',
'阶前甃清泉，洮颒冰雪冷',
'尝闻扫垩生雪白，颠草亲承担夫力',
'护持空雪竹，束缚欠霜毫',
'东阁尊空满，南枝雪半残',
'对雪同谁语，登楼似欲仙',
'竹椅蒲团深着意，雪窗萤案坐收功',
'坐想冰雪姿，萧然幽兴永',
'夕阳映雪低，晓露和烟滴',
'粉苞五出绛蜡趺，犯寒独逞冰雪肤',
'始贺今朝雪，隆寒特地严',
'坚姿工傲雪，直干上凌霄',
'娈彼闺房秀，泠然玉雪容',
'侵裾爽气冷冰雪，漱玉寒流锵珮环',
'笑折繁枝头带雪，想成青子颊生津',
'雪里寒梅岁又新，粘枝的皪已开匀',
