'雪霜贸贸添愁绝，蜂蝶纷纷预屏藏',
'石门高赚雪，溪坞曲藏梅',
'竹窗吟听雪，苔石坐看云',
'秋声凄万窍，雪意黯千峰',
'整冠叩仙阍，获礼冰雪容',
'雪腕荡兰舟，齐唱横塘曲',
'惟有冰雪姿，堪与琼瑶伍',
'颇欲学僧轩，洒粉作竹雪',
'潜动惊秋意，生从傲雪枝',
'高义杉松度冰雪，好诗星斗转璇玑',
'赖有新诗伴冰蘂，犯寒欺雪鬬宫妆',
'回途赓雪韵，门里绿苔新',
'要是穷冬正冰雪，斡回和气遍华夷',
'涤砚探题皆白雪，调琴奏曲尽清商',
'通江石泉滑，崩崖朝雪重',
