'凭莓阶、雪痕乍铺，那回已趁飞梅去',
'罗襟湿未干，又是凄凉雪',
'江湖岁晚听飞雪，但沙痕、空记行迹',
'飏芳丛、低翻雪羽，凝素艳、争簇冰蝉',
'积雪迷松迳，围炉掩竹扉',
