'纤腰妙舞萦回雪，皓齿清歌遏住云',
'结叶繁云色，凝琼遍雪华',
'起予歌赤阪，永好逾白雪',
'青阳御紫微，白雪下彤闱',
'艳雪凌空散，舞罗起徘徊',
'单飞后片雪，早晚及前侣',
