'冰池通极浦，雪径绕高岩',
'晓鸡惊树雪，寒鹜守冰池',
'陶诗只采黄金实，郢曲新传白雪英',
'晓程侵岭雪，远栈入溪云',
'巴歌掩白雪，鲍肆埋兰芳',
